using System.Text;
using System.Text.Json.Nodes;
using GPC.Checkers.Geotechnics.Seismic;
using GPC.Checkers.Geotechnics.Walls;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using static GeotechnicsTests.PilesFixture;
using static GeotechnicsTests.WallEdgeCaseTests;
using static GeotechnicsTests.WallsFixture;

namespace GeotechnicsTests;

/// <summary>
/// ANTHEA 1.14.4, step 1 of the census of the combinations (ANTHEA docs/refactoring/combinazioni-model-censimento.md §3.5): the combinations of
/// the wall generated by Model through the adapter <see cref="WallCombinations"/> are the rows of the frozen generator
/// <see cref="FrozenWallCombinations"/>, bit for bit, without tolerance: names, order, states, approach, purpose, flags, every factor and every
/// coefficient (bits of the doubles), and the same exception (type and message) where the generator refuses the input. Inputs: the documents of
/// the two wall captures of ANTHEA and 3000 walls drawn with a fixed seed. The only declared difference: the adapter refuses the inputs that
/// ANTHEA already refuses before the generation (ψ of a variable action outside 0 ≤ ψ2 ≤ ψ1 ≤ ψ0 ≤ 1, a group of correlated actions with two
/// natures), which the frozen generator accepted.
/// </summary>
[TestClass]
public class WallCombinationsEquivalenceTests
{
    public TestContext TestContext { get; set; } = null!;

    /// <summary>The rows of a generator as text with the bits of every double, or the refusal.</summary>
    static string Outcome(Func<WallInput, IReadOnlyList<WallCombination>> generate, WallInput input)
    {
        IReadOnlyList<WallCombination> rows;
        try { rows = generate(input); }
        catch (Exception e) { return "ERR " + e.GetType().FullName + " " + e.Message; }
        static string B(double v) => BitConverter.DoubleToInt64Bits(v).ToString("X16");
        var text = new StringBuilder();
        foreach (var r in rows)
        {
            text.Append(r.Name).Append('|').Append(r.State).Append('|').Append(r.Purpose).Append('|').Append(r.Approach).Append('|').Append(r.VariableSurchargeOnHeel);
            foreach (double v in new[] { r.Wall, r.Soil, r.ValleySoil, r.Water, r.FrictionFactor, r.SlidingFactor, r.OverturningFactor, r.BearingFactor, r.Kh, r.Kv, r.PassiveFactor })
                text.Append('|').Append(B(v));
            text.Append('|').Append(r.Coefficients.Count);
            foreach (var a in input.Actions) text.Append('|').Append(a.Id).Append('=').Append(B(r.Coefficients[a.Id]));
            text.Append('\n');
        }
        return text.ToString();
    }

    /// <summary>Inputs refused by ANTHEA before the generation (RetainingWall.ValidateActions) and now also by the adapter.</summary>
    static bool Declared(WallInput input)
    {
        var enabled = input.Actions.Where(a => a.Enabled).ToArray();
        return enabled.Any(a => a.Category == WallActionCategory.Q && !(a.Psi2 >= 0 && a.Psi2 <= a.Psi1 && a.Psi1 <= a.Psi0 && a.Psi0 <= 1))
            || enabled.GroupBy(a => a.Key).Any(g => g.Select(a => a.Category).Distinct().Count() > 1);
    }

    sealed class Tally { public int Rows, Refused, Declared, Inputs; public readonly Dictionary<string, int> Refusals = new(); public readonly List<string> DeclaredNames = new(); }

    static void Compare(WallInput input, string id, Tally tally)
    {
        tally.Inputs++;
        string adapter = Outcome(WallCombinations.Generate, input);
        if (Declared(input))
        {
            Assert.IsTrue(adapter.StartsWith("ERR System.Argument"), id + ": declared refusal expected, got rows");
            tally.Declared++; tally.DeclaredNames.Add(id); return;
        }
        string frozen = Outcome(FrozenWallCombinations.Generate, input);
        if (frozen != adapter)
        {
            var a = frozen.Split('\n'); var b = adapter.Split('\n'); int i = 0;
            while (i < Math.Min(a.Length, b.Length) && a[i] == b[i]) i++;
            Assert.Fail($"{id}: row {i} differs\nfrozen:  {(i < a.Length ? a[i] : "(end)")}\nadapter: {(i < b.Length ? b[i] : "(end)")}");
        }
        if (frozen.StartsWith("ERR ")) { tally.Refused++; string key = frozen.Length > 60 ? frozen[..60] : frozen; tally.Refusals[key] = tally.Refusals.TryGetValue(key, out int n) ? n + 1 : 1; }
        else tally.Rows += frozen.Count(c => c == '\n');
    }

    [TestMethod]
    public void TheDocumentsOfTheCapturesGiveTheSameRows()
    {
        var tally = new Tally(); int unreadable = 0;
        var documents = Lines("walls-combinations.jsonl").Select(l => (Str(l["name"]), l["input"] as JsonObject))
            .Concat(GzipLines("walls-documents.jsonl.gz").Select(l => (Str(l["name"]), l["input"] as JsonObject)));
        foreach (var (name, doc) in documents)
        {
            if (doc == null) { unreadable++; continue; }
            WallInput input;
            try { input = Input(doc); } catch (ArgumentException) { unreadable++; continue; }
            Compare(input, name, tally);
        }
        TestContext.WriteLine($"{tally.Inputs} documents, {tally.Rows} rows identical, {tally.Refused} identical refusals, {tally.Declared} declared refusals, {unreadable} not readable as WallInput");
        foreach (string name in tally.DeclaredNames) TestContext.WriteLine("  declared: " + name);
        Assert.IsTrue(tally.Inputs > 200 && tally.Rows > 3000, $"{tally.Inputs} documents, {tally.Rows} rows");
    }

    /// <summary>Walls drawn with a fixed seed: up to 9 actions of every nature and type, groups, ψ, disabled actions, heel, valley, water, seismic.</summary>
    static IEnumerable<WallInput> RandomWalls(int count)
    {
        var random = new Random(20261027);
        var categories = new[] { WallActionCategory.G1, WallActionCategory.G2, WallActionCategory.Q, WallActionCategory.Q, WallActionCategory.Q, WallActionCategory.A };
        var types = new[] { WallActionType.UniformSurcharge, WallActionType.UniformSurcharge, WallActionType.HorizontalForce, WallActionType.VerticalForce, WallActionType.Moment, WallActionType.LateralPressure };
        var psi = new[] { 0, .2, .3, .5, .6, .7, .8, 1 };
        var site = NtcSiteAmplification.Create(.15, (NtcSoilCategory.C, 2.5), null, (NtcTopography.Flat, 0, 0, 0), null);
        var strong = NtcSiteAmplification.Create(.5, (NtcSoilCategory.B, 2.5), null, (NtcTopography.Flat, 0, 0, 0), null);
        for (int n = 0; n < count; n++)
        {
            int actionCount = random.Next(0, 10); var actions = new List<WallAction>();
            var groupPsi = new Dictionary<string, (double, double, double)>();
            for (int i = 0; i < actionCount; i++)
            {
                var category = categories[random.Next(categories.Length)];
                var type = category == WallActionCategory.A ? (random.Next(2) == 0 ? WallActionType.Impact : WallActionType.HorizontalForce) : types[random.Next(types.Length)];
                string group = random.Next(10) < 4 ? category + "-" + random.Next(2) : "";
                double p0 = psi[random.Next(psi.Length)], p1 = psi.Where(p => p <= p0).ElementAt(random.Next(psi.Count(p => p <= p0))), p2 = psi.Where(p => p <= p1).ElementAt(random.Next(psi.Count(p => p <= p1)));
                if (group.Length > 0) { if (groupPsi.TryGetValue(group, out var g)) (p0, p1, p2) = g; else groupPsi[group] = (p0, p1, p2); }
                // One action in 40 with ψ out of order, one in 40 in a group of another nature: refused by ANTHEA, declared refusals here.
                if (random.Next(40) == 0) (p0, p1) = (p1 * .5, p0 == 0 ? .5 : p0);
                if (random.Next(40) == 0 && group.Length == 0 && actions.Count > 0 && actions[^1].Group.Length > 0) group = actions[^1].Group;
                actions.Add(new WallAction("a" + i, "Azione " + i, type, category, 10, 2000, 500, 900, p0, p1, p2, group, random.Next(100) < 85));
            }
            bool heel = random.Next(4) > 0;
            var valley = random.Next(3) == 0 ? new WallValley(1000, Column(1, (Fill(), 5))) : null;
            var water = random.Next(3) == 0 ? new WallWater(1000) : null;
            WallSeismic? seismic = random.Next(6) switch
            {
                0 => WallSeismic.Assigned(WallSeismicMethod.MononobeOkabe, .1, 0),
                1 => WallSeismic.Assigned(WallSeismicMethod.Wood, .2, .05),
                2 => WallSeismic.FromSite(WallSeismicMethod.MononobeOkabe, site),
                3 => random.Next(4) == 0 ? WallSeismic.FromSite(WallSeismicMethod.Wood, strong) : null,
                _ => null
            };
            yield return heel ? Wall(valley: valley, water: water, actions: actions, seismic: seismic) : Wall(toe: 2.7, heel: 0, valley: valley, water: water, actions: actions, seismic: seismic);
        }
    }

    [TestMethod]
    public void RandomWallsGiveTheSameRows()
    {
        var tally = new Tally(); int n = 0;
        foreach (var input in RandomWalls(3000)) Compare(input, "random " + n++, tally);
        // The two limits of the rows: more than 12 factors before the generation, more than 4096 rows during it.
        var limits = new List<WallAction> { Surcharge(10) };
        for (int i = 0; i < 7; i++) limits.Add(new WallAction("g" + i, "G " + i, WallActionType.HorizontalForce, WallActionCategory.G1, 10, 2000));
        Compare(Wall(valley: new WallValley(1000, Column(1, (Fill(), 5))), water: new WallWater(1000), actions: limits), "4096 rows", tally);
        Compare(Wall(water: new WallWater(1000), actions: limits.Append(new WallAction("g7", "G 7", WallActionType.HorizontalForce, WallActionCategory.G1, 10, 2000))), "12 factors", tally);
        TestContext.WriteLine($"{tally.Inputs} walls, {tally.Rows} rows identical, {tally.Refused} identical refusals, {tally.Declared} declared refusals");
        foreach (var (key, value) in tally.Refusals) TestContext.WriteLine($"  {value} × {key}");
        Assert.IsTrue(tally.Rows > 50000, "rows " + tally.Rows);
        Assert.IsTrue(tally.Declared > 0, "declared refusals exercised");
        foreach (string refusal in new[] { "Oltre 4096", "Generazione troppo estesa", "Sisma Generale" })
            Assert.IsTrue(tally.Refusals.Keys.Any(k => k.Contains(refusal)), "refusal exercised: " + refusal);
    }

    /// <summary>The combinations of the global stability as text with the bits of every double, or the refusal.</summary>
    static string GlobalOutcome(Func<IReadOnlyList<GPC.Checkers.Geotechnics.Slopes.SlopeFactors>> generate, WallInput input)
    {
        IReadOnlyList<GPC.Checkers.Geotechnics.Slopes.SlopeFactors> rows;
        try { rows = generate(); }
        catch (Exception e) { return "ERR " + e.GetType().FullName + " " + e.Message; }
        static string B(double v) => BitConverter.DoubleToInt64Bits(v).ToString("X16");
        var text = new StringBuilder();
        foreach (var r in rows)
        {
            text.Append(r.Name).Append('|').Append(r.Undrained);
            foreach (double v in new[] { r.SoilWeight, r.BodyWeight, r.TanFrictionAngle, r.EffectiveCohesion, r.UndrainedShearStrength, r.ResistanceFactor, r.Kh, r.Kv }) text.Append('|').Append(B(v));
            text.Append('|').Append(r.Loads.Count);
            foreach (var a in input.Actions) text.Append('|').Append(a.Id).Append('=').Append(B(r.Loads[a.Id]));
            text.Append('\n');
        }
        return text.ToString();
    }

    /// <summary>
    /// Step 2 of the census: A2, M2 and γR of the global stability of the wall come from Model; the combinations are those of the frozen code bit
    /// for bit, static, accidental and seismic (assigned ±kv), drained and undrained, on the same walls.
    /// </summary>
    [TestMethod]
    public void GlobalCombinationsAreTheSame()
    {
        int compared = 0, rows = 0, refused = 0, declared = 0, n = 0;
        foreach (var input in RandomWalls(1500))
        {
            var seismic = (n % 3) switch { 0 => null, 1 => WallGlobalSeismic.Assigned(.1, .05), _ => WallGlobalSeismic.Assigned(.08, 0) };
            bool undrained = n % 2 == 0; string id = "random " + n++;
            string adapter = GlobalOutcome(() => WallGlobalStability.Combinations(input, seismic, undrained), input);
            if (Declared(input)) { Assert.IsTrue(adapter.StartsWith("ERR System.Argument"), id + ": declared refusal expected"); declared++; continue; }
            string frozen = GlobalOutcome(() => FrozenWallCombinations.Global(input, seismic, undrained), input);
            Assert.AreEqual(frozen, adapter, id);
            compared++; if (frozen.StartsWith("ERR ")) refused++; else rows += frozen.Count(c => c == '\n');
        }
        TestContext.WriteLine($"{compared} walls, {rows} global rows identical, {refused} identical refusals, {declared} declared refusals");
        Assert.IsTrue(rows > 10000 && refused > 0, $"{rows} rows, {refused} refusals");
    }
}
